// Internal streaming protocol: LE u32 kind/frames/sequence/JSON-length, JSON,
// then planar float32 PCM. Replies: LE JSON-length, JSON metadata, planar PCM.
static bool readExact(void *buffer,size_t count,bool eof=false){size_t pos=0;while(pos<count){auto n=read(STDIN_FILENO,(char *)buffer+pos,count-pos);if(n==0&&pos==0&&eof)return false;require(n>0,"Plugin stream input closed");pos+=n;}return true;}
static void writeExact(const void *buffer,size_t count){size_t pos=0;while(pos<count){auto n=write(protocolFd,(const char *)buffer+pos,count-pos);require(n>0,"Plugin stream output closed");pos+=n;}}
